              {key:'businessName', lbl:'BUSINESS NAME',  ph:'e.g. VivoPop Store'},
              {key:'sellerName',   lbl:'YOUR NAME',       ph:'e.g. Rahul'},
              {key:'businessPhone',lbl:'PHONE NUMBER',    ph:'e.g. 9876543210'},
              {key:'businessUPI',  lbl:'UPI ID',          ph:'e.g. rahul@upi'},
