          <div style={{display:'flex',gap:10}}>
            <button className="btn-primary" onClick={handleUpdateBulk}>Update</button>
            <button className="btn-outline" onClick={()=>setEditBulk(null)}>Cancel</button>
          </div>
        </div></div>
      )}

      {/* WHATSAPP MODAL */}
      {waOrder&&(
        <div style={S.modal}><div style={{...S.mbox,minWidth:520,maxWidth:560}}>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
            <div style={{color:'#25D366',fontWeight:800,fontSize:15,fontFamily:'Syne,sans-serif'}}>📱 WhatsApp Message</div>
            <button className="btn-outline" style={{padding:'5px 12px',fontSize:12}} onClick={()=>setWaOrder(null)}>✕ Close</button>
          </div>
          <div style={{background:'#0d1020',borderRadius:10,padding:16,marginBottom:16,fontFamily:'Space Mono,monospace',fontSize:12,lineHeight:1.8,color:'#e8eaf0',whiteSpace:'pre-wrap',maxHeight:340,overflowY:'auto',border:'1px solid #1a2040'}}>
            {buildWhatsAppMsg(waOrder,settings.businessName)}
