                  <td colSpan={2} style={{padding:'8px'}}>TOTAL</td>
                  <td style={{padding:'8px',textAlign:'center'}}>{fmtK(invoiceOrder.quantity)}</td>
                  <td style={{padding:'8px',textAlign:'right'}}>{fmtRs(invoiceOrder.earnings)}</td>
                </tr>
              </tbody>
            </table>
            {settings.businessUPI&&<div style={{fontSize:12,color:'#333'}}>💳 UPI: <strong style={{color:'#5b6fff'}}>{settings.businessUPI}</strong></div>}
          </div>
          <div style={{display:'flex',gap:10}}>
            <button className="btn-primary" style={{flex:1}} onClick={()=>handlePrintInvoice(invoiceOrder)}>🖨 Print / Save as PDF</button>
            <button className="btn-outline" onClick={()=>setInvoiceOrder(null)}>Close</button>
          </div>
          <div style={{fontSize:11,color:'#4a5278',fontFamily:'Space Mono,monospace',marginTop:10,textAlign:'center'}}>
